// Legendary items from Data Dragon (generated by tools/build_items.py). There is no recipe: a level up offers a new
// legendary or one more level for an owned one, like the weapons of a survivors game. An item's stats and passive
// start capped and grow with its level (STAT_SCALE, PASSIVE_POWER) up to MAX_LEVEL.
import { t, type Key } from './i18n';
import data from './items.json';

export interface ItemStats {
  ad?: number; ap?: number; as?: number; hp?: number; mana?: number; crit?: number; armor?: number; mr?: number; msPct?: number;
  lifesteal?: number; omnivamp?: number; ah?: number; armorPen?: number; lethality?: number; magicPen?: number; magicPenFlat?: number;
  critDamage?: number; tenacity?: number; ms?: number; // ms: flat Move Speed (boots)
}
export type ItemPool = 'ad' | 'ap';
export interface Item {
  id: string;
  name: string;
  stats: ItemStats;
  pools: ItemPool[]; // champions it is offered to (ChampionDef.itemPool)
}

const AD_STATS: (keyof ItemStats)[] = ['ad', 'as', 'crit', 'critDamage', 'armorPen', 'lethality'];
const AP_STATS: (keyof ItemStats)[] = ['ap', 'magicPen', 'magicPenFlat'];
/** AD champions get items with an attack stat, AP ones items with AP; hybrids and items with neither (tanks) go to both. */
function poolsOf(s: ItemStats): ItemPool[] {
  const ad = AD_STATS.some((k) => s[k]), ap = AP_STATS.some((k) => s[k]);
  return [...(ad || !ap ? ['ad' as const] : []), ...(ap || !ad ? ['ap' as const] : [])];
}

// names live in src/locales (`item.<id>`, written by tools/build_items.py)
const VAMP_MULT = 0.01; // item Life Steal / Omnivamp sustain too much against hordes: 10% in LoL gives 0.1% here
const toItems = (src: Record<string, { stats: ItemStats }>): Record<string, Item> => Object.fromEntries(Object.entries(src).map(([id, it]) => {
  const stats: ItemStats = { ...it.stats };
  if (stats.lifesteal) stats.lifesteal *= VAMP_MULT;
  if (stats.omnivamp) stats.omnivamp *= VAMP_MULT;
  return [id, { id, stats, pools: poolsOf(stats), name: t(`item.${id}` as Key) }];
}));
export const ITEMS = toItems(data.items);

/**
 * Boots: their own slot, outside the six. Boots at BOOTS_AT; killing the Rift Scuttler offers the tier 2 boots (the
 * keys), killing the dragon turns them into their tier 3 (the values). Their stats don't level up.
 */
export const BOOTS = toItems(data.boots);
export const BOOTS_FIRST = '1001';
export const BOOTS_AT = 300;
export const BOOT_UPGRADES: Record<string, string> = { '3006': '3172', '3020': '3175', '3047': '3174', '3111': '3173', '3158': '3171', '3009': '3170' };
/** Plating (Plated Steelcaps, Armored Advance): physical hits deal 10% less. */
export const PLATING = new Set(['3047', '3174']);
export const MAX_ITEMS = 6;
export const MAX_LEVEL = 5;
/** Fraction of the item's stats at each level (index = level - 1). */
export const STAT_SCALE = [0.4, 0.55, 0.7, 0.85, 1];
/** Strength of the item's passive at each level: locked below PASSIVE_LEVEL, its full numbers at MAX_LEVEL. */
export const PASSIVE_POWER = [0, 0, 0.6, 0.8, 1];
export const PASSIVE_LEVEL = PASSIVE_POWER.findIndex((p) => p > 0) + 1;
export const itemIcon = (id: string) => `https://ddragon.leagueoflegends.com/cdn/${data.version}/img/item/${id}.png`;

// Passive descriptions and effects: src/itemEffects.ts

/** An inventory slot: the item and its level (1..MAX_LEVEL). */
export interface Slot { id: string; level: number }
export const buildComplete = (slots: Slot[]) => slots.length === MAX_ITEMS && slots.every((s) => s.level >= MAX_LEVEL);

/** A level-up offer: a new item, or the next level of owned slot `slot`. */
export interface Offer { id: string; slot: number; kind: 'new' | 'level' }

/**
 * Up to `count` distinct offers drawn at random: levels for owned items below MAX_LEVEL and, while a slot is free,
 * new items of the champion's pool. Items of the recommended `build` are three times as likely, owned ones twice.
 */
export function rollOffers(slots: Slot[], pool: ItemPool, build: readonly string[] = [], count = 3): Offer[] {
  const cands: (Offer & { w: number })[] = slots.flatMap((s, slot) => (s.level < MAX_LEVEL ? [{ id: s.id, slot, kind: 'level' as const, w: 2 }] : []));
  if (slots.length < MAX_ITEMS) {
    for (const it of Object.values(ITEMS)) {
      if (it.pools.includes(pool) && !slots.some((s) => s.id === it.id)) cands.push({ id: it.id, slot: slots.length, kind: 'new', w: 1 });
    }
  }
  for (const c of cands) if (build.includes(c.id)) c.w *= 3;
  const out: Offer[] = [];
  while (out.length < count && cands.length) {
    let r = Math.random() * cands.reduce((a, c) => a + c.w, 0);
    const i = Math.max(0, cands.findIndex((c) => (r -= c.w) < 0));
    const { w: _, ...o } = cands.splice(i, 1)[0];
    out.push(o);
  }
  return out;
}

/** Recommendation score (higher is better): items of the build first, levelling them before starting new ones. */
export function offerScore(o: Offer, slots: Slot[], build: readonly string[]) {
  const rec = build.includes(o.id) ? 10 : 0;
  return o.kind === 'level' ? rec + 5 + slots[o.slot].level : rec + (slots.length < 3 ? 4 : 0);
}

export const POTION = { hp: 0.05, mana: 0.05 }; // fraction of max HP / mana restored by the build-complete potions
/** The build-complete potions (also offered by Triple Tonic): name and effect text. */
export const POTIONS = {
  hp: {
    icon: '2003',
    name: t('potion.hp.name'),
    text: t('potion.hp.text'),
  },
  mana: {
    icon: '2031',
    name: t('potion.mana.name'),
    text: t('potion.mana.text'),
  },
};
export const LEGENDARY_BONUS = 0.5; // blueprint: +50% of the item's stats
export const BLUEPRINT_CHANCE = 0.01; // per kill, once the build is complete

/** An item's stats at `level`. */
export function statsAt(id: string, level: number, mult = 1): ItemStats {
  const k = STAT_SCALE[level - 1] * mult;
  return Object.fromEntries(Object.entries(ITEMS[id].stats).map(([s, v]) => [s, v * k]));
}

const STAT_KEYS: (keyof ItemStats)[] = ['ad', 'ap', 'as', 'hp', 'mana', 'crit', 'armor', 'mr', 'msPct', 'lifesteal', 'omnivamp', 'ah',
  'armorPen', 'lethality', 'magicPen', 'magicPenFlat', 'critDamage', 'tenacity', 'ms'];
// penetration doesn't stack additively in LoL; keep the best source
const BEST_OF = new Set<keyof ItemStats>(['armorPen', 'magicPen']);

/** Stats of the current slots plus the boots; `legendary` is the slot upgraded by the blueprint (-1 for none). */
export function sumStats(slots: Slot[], legendary = -1, boots: string | null = null): Required<ItemStats> {
  const s = Object.fromEntries(STAT_KEYS.map((k) => [k, 0])) as Required<ItemStats>;
  const all = slots.map((slot, i) => statsAt(slot.id, slot.level, i === legendary ? 1 + LEGENDARY_BONUS : 1));
  if (boots) all.push(BOOTS[boots].stats);
  for (const stats of all) {
    for (const [k, v] of Object.entries(stats) as [keyof ItemStats, number][]) s[k] = BEST_OF.has(k) ? Math.max(s[k], v) : s[k] + v;
  }
  return s;
}

const PERCENT = new Set<keyof ItemStats>(['as', 'crit', 'msPct', 'lifesteal', 'omnivamp', 'armorPen', 'magicPen', 'critDamage', 'tenacity']);
const sign = (v: number) => (v < 0 ? '−' : '+');
const pctFormat = new Intl.NumberFormat(t('meta.tag'), { maximumFractionDigits: 2 }); // 0,07% in pt/es
export const statValue = (k: keyof ItemStats, v: number) =>
  (PERCENT.has(k) ? `${pctFormat.format(Math.abs(v * 100))}%` : String(Math.abs(Math.round(v))));
const statLabel = (k: keyof ItemStats, v: number) => `${sign(v)}${statValue(k, v)} ${t(`stat.${k}`)}`;
export const describeStats = (s: ItemStats, mult = 1) =>
  Object.entries(s).map(([k, v]) => statLabel(k as keyof ItemStats, v * mult)).join(' · ');
